function tocOffset(){var hd=document.querySelector(".hd"),off=(hd?hd.getBoundingClientRect().height:68)+16;var t=document.querySelector(".toc");if(t&&getComputedStyle(t).flexDirection==="row")off+=t.getBoundingClientRect().height;return off}
function tocSet(id){document.querySelectorAll(".toc a").forEach(function(a){var on=a.dataset.s===id;a.classList.toggle("on",on);if(on&&a.parentNode.scrollWidth>a.parentNode.clientWidth){a.parentNode.scrollTo({left:a.offsetLeft-16,behavior:"smooth"})}})}
function tocCurrent(){var secs=document.querySelectorAll(".card2");if(!secs.length)return;var off=tocOffset()+40,cur=secs[0].id.slice(2);
 secs.forEach(function(s){if(s.getBoundingClientRect().top<=off)cur=s.id.slice(2)});
 if(window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-4)cur=secs[secs.length-1].id.slice(2);
 tocSet(cur)}
function tocGo(id,smooth){var el=document.getElementById("s-"+id);if(!el)return;var y=el.getBoundingClientRect().top+window.scrollY-tocOffset();
 TOCLOCK=Date.now();tocSet(id);window.scrollTo({top:Math.max(0,y),behavior:smooth&&!matchMedia("(prefers-reduced-motion: reduce)").matches?"smooth":"auto"})}
document.addEventListener("click",function(e){var a=e.target.closest(".toc a[data-s]");if(!a)return;e.preventDefault();tocGo(a.dataset.s,true)},true);
var _tocT=0;window.addEventListener("scroll",function(){var n=Date.now();if(n-TOCLOCK<900||n-_tocT<60)return;_tocT=n;tocCurrent()},{passive:true});window.addEventListener("scrollend",function(){TOCLOCK=0;tocCurrent()});
