/* прицел в настоящих пикселях CS2: разрыв от центра, длина и толщина из кода; одно игровое px = k экранных */
function xhSvg(x,w){var k=Math.max(2,Math.round(w/50)),T=Math.max(1,x.thick|0),G=Math.max(0,x.gap|0),L=Math.max(0,x.size|0),o=x.outline?1:0;
 var r=G+L+o+Math.ceil(T/2)+1,N=2*r,c=r,h=T/2,R=[],B=[];
 function rect(cls,X,Y,W,H){if(W<=0||H<=0)return;if(o)B.push('<rect x="'+(X-o)+'" y="'+(Y-o)+'" width="'+(W+2*o)+'" height="'+(H+2*o)+'"/>');R.push('<rect'+(cls?' class="a '+cls+'"':'')+' x="'+X+'" y="'+Y+'" width="'+W+'" height="'+H+'"/>')}
 if(!x.only){rect("ar",c+G,c-h,L,T);rect("al",c-G-L,c-h,L,T);rect("ad2",c-h,c+G,T,L);rect("au",c-h,c-G-L,T,L)}
 if(x.dot||x.only)rect("",c-h,c-h,T,T);
 var px=N*k,op=(x.alpha/255).toFixed(2);
 return '<svg width="'+px+'" height="'+px+'" viewBox="0 0 '+N+' '+N+'" shape-rendering="crispEdges" aria-hidden="true" style="overflow:visible">'+(o?'<g fill="#000" opacity="'+op+'">'+B.join("")+'</g>':'')+'<g fill="'+x.hex+'" fill-opacity="'+op+'">'+R.join("")+'</g></svg>'}

