function newDecode(code){var s=(code||"").trim();if(!/^CS[A-Za-z0-9]{44}$/.test(s)||/^CSGO/i.test(s))return null;var b=b57dec(s.slice(2),32);if(!b)return null;var sum=0;for(var i=1;i<32;i++)sum+=b[i];if(sum%256!==b[0])return null;
 return {h:b[2]|(b[3]<<8),style:b[4]&31,dot:(b[4]>>6)&1,t:(b[4]>>7)&1,rgb:[b[5],b[6],b[7]],alpha:b[8],thick:b[13]&63,outline:b[13]>>6?1:0,gap:s8(b[14]),length:b[16]}}
