 if(ok.length)h+='<div><h3>'+L("Частые соперники","Frequent opponents",{})+'</h3><ul class="tl-o">'+ok.map(function(k){return '<li><b>'+esc(k)+'</b><span><em class="w">'+opp[k][0]+'</em> : <em class="l">'+opp[k][1]+'</em></span></li>'}).join("")+'</ul></div>';
